function setSelection(s,from,to){if(recording){toast('Stop your recording before changing passages.');return;}stopListening(false);stopAudio();s=Math.max(1,Math.min(114,Number(s)));const count=quran[s-1].verses.length;from=Math.max(1,Math.min(count,Number(from)||1));to=Math.max(from,Math.min(count,Number(to)||from));speechStatus='Tap Start listening, allow the microphone, then recite.';speechProblem='';state.selection={surah:s,from,to};state.readerCursor=null;state.quiz=null;state.hintCount=0;latestAlignment=null;latestTranscript='';save();render();}
